t-sm"></label><label class="text-xs flex-1 min-w-48">Notes<input name="notes" class="block mt-1 border rounded px-2 py-2 text-sm w-full"></label><button class="px-3 py-2 border rounded text-sm">Apply to selected</button></div></form>
